const fs = await import('fs');
const path = await import('path');
const dir = 'vibe-coding-ppt/tutorials-content';
const expected = {
  'cc-01': ['CC-01','Claude Code完整安装指南'],
  'cc-02': ['CC-02','基础使用完整指南'],
  'cc-03': ['CC-03','Commands系统完整指南'],
  'cc-04': ['CC-04','MCP集成完整指南'],
  'cc-05': ['CC-05','Hooks系统完整指南'],
  'cc-06': ['CC-06','Subagent子代理完整指南'],
  'cc-07': ['CC-07','Skills定制完整指南'],
};
const allowed = new Set(['cover','section','bullets','cards','table','steps','quote','end']);
const cn = s => Array.from(s.replace(/\s/g,'')).length;
const problems = [];
const summary = [];
for (const [code, [expCode, expTitle]] of Object.entries(expected)) {
  const fp = path.join(dir, code + '.json');
  let raw, obj;
  try { raw = fs.readFileSync(fp, 'utf8'); } catch(e) { problems.push(`${code}: 文件不存在`); continue; }
  try { obj = JSON.parse(raw); } catch(e) { problems.push(`${code}: JSON 解析失败 ${e.message}`); continue; }
  if (obj.code !== expCode) problems.push(`${code}: code=${obj.code}`);
  if (obj.category !== 'claude-code') problems.push(`${code}: category=${obj.category}`);
  if (obj.fileTitle !== expTitle) problems.push(`${code}: fileTitle=${obj.fileTitle}`);
  if (!Array.isArray(obj.slides)) { problems.push(`${code}: slides 不是数组`); continue; }
  const n = obj.slides.length;
  if (n < 10 || n > 14) problems.push(`${code}: slides=${n}`);
  if (obj.slides[0].layout !== 'cover') problems.push(`${code}: 首张不是 cover`);
  if (obj.slides[n-1].layout !== 'end') problems.push(`${code}: 末张不是 end`);
  if (obj.slides[0].kicker !== `Vibe Coding 学习系列 · ${expCode}`) problems.push(`${code}: kicker=${obj.slides[0].kicker}`);
  obj.slides.forEach((s, i) => {
    const tag = `${code} slide${i+1}(${s.layout})`;
    if (!allowed.has(s.layout)) problems.push(`${tag}: 未知 layout`);
    if (!s.title) problems.push(`${tag}: 缺 title`);
    if (s.layout === 'bullets') {
      const b = s.bullets || [];
      if (b.length > 5) problems.push(`${tag}: bullets=${b.length}`);
      b.forEach((x, j) => { if (cn(x) > 42) problems.push(`${tag} bullet${j+1}: ${cn(x)} 字「${x}」`); });
    }
    if (s.layout === 'cards') {
      const c = s.cards || [];
      if (c.length < 3 || c.length > 4) problems.push(`${tag}: cards=${c.length}`);
      c.forEach((x, j) => { if (!x.title || !x.desc) problems.push(`${tag} card${j+1}: 缺字段`); if (cn(x.desc) > 42) problems.push(`${tag} card${j+1} desc: ${cn(x.desc)} 字`); });
    }
    if (s.layout === 'steps') {
      const st = s.steps || [];
      if (st.length < 3 || st.length > 4) problems.push(`${tag}: steps=${st.length}`);
      st.forEach((x, j) => { if (!x.title || !x.desc) problems.push(`${tag} step${j+1}: 缺字段`); if (cn(x.desc) > 42) problems.push(`${tag} step${j+1} desc: ${cn(x.desc)} 字「${x.desc}」`); });
    }
    if (s.layout === 'table') {
      const h = s.headers || [], r = s.rows || [];
      if (h.length > 5) problems.push(`${tag}: 表头 ${h.length} 列`);
      if (r.length > 6) problems.push(`${tag}: ${r.length} 行`);
      r.forEach((row, j) => { if (row.length !== h.length) problems.push(`${tag} row${j+1}: ${row.length} 列 != ${h.length}`); });
    }
  });
  summary.push({ code, deck: obj.deck, slides: n });
}
console.log('=== SUMMARY ===');
summary.forEach(s => console.log(`${s.code} | ${s.deck} | ${s.slides} 张`));
console.log('\n=== PROBLEMS (' + problems.length + ') ===');
problems.forEach(p => console.log(p));
", "description": "Validate all 7 JSON files against schema constraints"}

